-- GENERATED by `wfj generate` from data/spell/spell-0401.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("spell", {
  [401488] = { "Incidi sui tuoi gambali la runa Assalto d'Ombra:\n\n$I1\nTi teletrasporti alle spalle del bersaglio e lo colpisci, infliggendo il $N1% dei danni dell'arma. Utilizzabile solo in Furtività. Fornisce $N2 punti combo.", nil, 0x2b51ff0b, nil, "um" },
  [401722] = { "Incidi sul tuo mantello la runa Sbarramento Arcano:\n\n$I1\nScaglia diversi missili contro il nemico bersaglio, infliggendo $N1 danni da arcano. Questo incantesimo ha anche una probabilità del $N2% di attivare Raffica di Missili.", nil, 0x948d9b5e, nil, "um" },
  [401749] = { "Incidi sul tuo elmo la runa Serie Bollente:\n\n$I1\nI colpi critici non periodici di Palla di Fuoco, Palla di Fuocogelo, Detonazione di Fuoco e Bruciatura riducono del $N2% il tempo di lancio della tua prossima Pirosfera lanciata entro $D1, effetto che si accumula fino a $N3 volte. Detonazione di Fuoco conferisce un accumulo aggiuntivo ogni volta che infligge danni.", nil, 0xcad31fdf, nil, "um" },
  [401752] = { "Incidi sui tuoi stivali la runa Mente Fredda:\n\n$I1\nI tuoi incantesimi che infliggono danni da gelo con effetti di raggelamento hanno una probabilità del $N1% di rendere istantaneo e senza costo in mana il tuo prossimo incantesimo Palla di Fuoco, Dardo di Geloincanto, Balefire Bolt o Palla di Fuocogelo.", nil, 0x90851280, nil, "um" },
  [401754] = { "Incidi sul tuo elmo la runa Advanced Warding:\n\n$I1\nI tuoi incantesimi Scudo di Mana, Protezione dal Gelo e Guardia di Fuoco ora possono essere lanciati su qualsiasi bersaglio amico e assorbono il $N1% di danni in più, e Scudo di Mana consuma il $N2% di mana in meno per ogni danno assorbito. Inoltre, il tuo Remove Lesser Curse è sostituito da Remove Greater Curse.\n\n$I2\nRimuove $N3 maledizione e $N4 effetto magico dannoso da un bersaglio amico.", nil, 0xae017b08, nil, "um" },
  [401757] = { "Incidi sui tuoi guanti la runa ⟦Arcane Blast=Detonazione Arcana⟧:\n\n$I1\nInveste il bersaglio con un'esplosione di energia, infliggendo $N1 danni da arcano. Ogni volta che lanci ⟦Arcane Blast=Detonazione Arcana⟧, ottieni il $N2% del tuo Intelletto come danni magici e il costo in mana di ⟦Arcane Blast=Detonazione Arcana⟧ aumenta del $N3%. L'effetto si accumula fino a $N4 volte e dura $D1 dalla prima applicazione.", nil, 0x8e71b319, nil, "um" },
  [401759] = { "Incidi sulla tua armatura per il torso la runa Surriscaldamento:\n\n$I1\nAumenta del $N1% la probabilità di critico magico di tutti i tuoi incantesimi, ma i tuoi critici magici non periodici hanno ora un costo aggiuntivo in mana pari al $N2% del tuo mana base.", nil, 0x32623dd4, nil, "um" },
  [401760] = { "Incidi sui tuoi guanti la runa Lancia di Ghiaccio:\n\n$I1\nInfligge $N1 danni da gelo a un nemico bersaglio. Infligge il $N2% di danni in più ai bersagli congelati.", nil, 0x38968448, nil, "um" },
  [401761] = { "Incidi sui tuoi bracciali la runa Riavvolgimento Temporale:\n\n$I1\nIl tuo bersaglio attuale con Temporal Beacon guarisce istantaneamente tutti i danni subiti negli ultimi $N1 s. Inefficace sui bersagli che non avevano Temporal Beacon $N2 s prima.", nil, 0x5aca7557, nil, "um" },
  [401762] = { "Incidi sulla tua cintura la runa Palla di Fuocogelo:\n\n$I1\nScaglia un dardo di fuocogelo contro il nemico, infliggendo $N1 danni da fuocogelo, rallentandone la velocità di movimento del $N2% e infliggendo altri $N3 danni da fuocogelo in $D1. Per questo incantesimo vale la più bassa tra le resistenze al gelo e al fuoco del bersaglio, e conta sia come danni da gelo sia come danni da fuoco.", nil, 0x699fda74, nil, "um" },
  [401763] = { "Incidi sulla tua cintura la runa Raffica di Missili:\n\n$I1\nConferisce al tuo incantesimo Detonazione Arcana una probabilità del $N1%, e ai tuoi incantesimi Ira Arcana, Palla di Fuoco, Dardo di Gelo, Detonazione del Gelo e Palla di Fuocogelo una probabilità del $N2%, di ridurre del $N3% la durata della canalizzazione del tuo prossimo incantesimo Missili Arcani, di ridurne il costo in mana del $N4% e di far partire i missili ogni $D1.", nil, 0x90adccfe, nil, "um" },
  [401764] = { "Incidi sul tuo mantello la runa Surriscaldamento:\n\n$I1\nDetonazione di Fuoco infligge sempre un colpo critico, può essere lanciata mentre lanci un altro incantesimo e non è soggetta al tempo di recupero globale, ma il suo tempo di recupero aumenta a $D1.", nil, 0x8ba49575, nil, "um" },
  [401765] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Dita di Gelo:\n\n$I1\nConferisce ai tuoi effetti di raggelamento una probabilità del $N1% di farti ottenere l'effetto Dita di Gelo, che fa trattare i tuoi prossimi $N2 incantesimi lanciati come se il bersaglio fosse congelato. Dura $D1.", nil, 0xccde94fb, nil, "um" },
  [401767] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Rigenerazione:\n\n$I1\nCura il bersaglio di $N1 salute in $D1 e applica Temporal Beacon per $D2. \n\nTemporal Beacon\n$I2\nRegistra la posizione spazio-temporale del soggetto. Il $N4% di tutti i danni da arcano inflitti dall'incantatore viene convertito in cure cronomantiche su ciascuno dei bersagli attuali di Temporal Beacon dell'incantatore. Questa cura è ridotta del $N5% su sé stessi, e ridotta anche del $N6% quando i danni sono inflitti da incantesimi arcani che colpiscono più bersagli.", nil, 0xf111a62e, nil, "um" },
  [401768] = { "Incidi sui tuoi gambali la runa Fiamma Vivente:\n\n$I1\nEvoca una fiamma di fuocoincanto che si muove verso il bersaglio, lasciando una scia di fuocoincanto. La scia infligge $N1 danni da fuocoincanto ogni secondo ai nemici vicini. Dura $D1.", nil, 0x4d4c79bc, nil, "um" },
})
